import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { IndianRupee, TrendingUp, Clock, CheckCircle, Download } from 'lucide-react';
import AgentCommissionRow from '../components/AgentCommissionRow';
import toast from 'react-hot-toast';

const mockCommissions = [
  { id: 'COMM-001', bookingId: 'BK-001', customer: 'Arjun Sharma', package: 'Golden Triangle Tour', bookingAmount: 45000, commissionAmount: 3600, commissionRate: 8, payoutStatus: 'paid', earnedDate: '2026-03-20', payoutDate: '2026-04-01' },
  { id: 'COMM-002', bookingId: 'BK-002', customer: 'Priya Patel', package: 'Kerala Backwaters', bookingAmount: 38500, commissionAmount: 3080, commissionRate: 8, payoutStatus: 'pending', earnedDate: '2026-04-01', payoutDate: null },
  { id: 'COMM-003', bookingId: 'BK-003', customer: 'Rahul Gupta', package: 'Goa Beach', bookingAmount: 22000, commissionAmount: 1760, commissionRate: 8, payoutStatus: 'paid', earnedDate: '2026-03-15', payoutDate: '2026-04-01' },
  { id: 'COMM-004', bookingId: 'BK-004', customer: 'Ananya Singh', package: 'Manali Trek', bookingAmount: 31000, commissionAmount: 2480, commissionRate: 8, payoutStatus: 'pending', earnedDate: '2026-04-05', payoutDate: null },
  { id: 'COMM-005', bookingId: 'BK-005', customer: 'Vikram Reddy', package: 'Andaman Explorer', bookingAmount: 55000, commissionAmount: 4400, commissionRate: 8, payoutStatus: 'pending', earnedDate: '2026-04-08', payoutDate: null },
  { id: 'COMM-006', bookingId: 'BK-006', customer: 'Kavya Nair', package: 'Rajasthan Heritage', bookingAmount: 41500, commissionAmount: 0, commissionRate: 8, payoutStatus: 'failed', earnedDate: '2026-03-25', payoutDate: null },
  { id: 'COMM-007', bookingId: 'BK-007', customer: 'Rohan Mehta', package: 'Varanasi Spiritual', bookingAmount: 18000, commissionAmount: 1440, commissionRate: 8, payoutStatus: 'paid', earnedDate: '2026-03-10', payoutDate: '2026-04-01' },
  { id: 'COMM-008', bookingId: 'BK-008', customer: 'Divya Joshi', package: 'Darjeeling Tea Tour', bookingAmount: 27500, commissionAmount: 2200, commissionRate: 8, payoutStatus: 'paid', earnedDate: '2026-03-05', payoutDate: '2026-03-15' },
];

const AgentCommissionsPage = () => {
  const [filter, setFilter] = useState('all');

  const filtered = mockCommissions.filter((c) => filter === 'all' || c.payoutStatus === filter);

  const totalEarned = mockCommissions.reduce((s, c) => s + c.commissionAmount, 0);
  const totalPaid = mockCommissions.filter((c) => c.payoutStatus === 'paid').reduce((s, c) => s + c.commissionAmount, 0);
  const totalPending = mockCommissions.filter((c) => c.payoutStatus === 'pending').reduce((s, c) => s + c.commissionAmount, 0);

  const exportCSV = () => {
    const headers = ['Commission ID', 'Booking ID', 'Customer', 'Package', 'Booking Amount', 'Commission', 'Rate', 'Status', 'Earned Date'];
    const rows = filtered.map((c) => [c.id, c.bookingId, c.customer, c.package, c.bookingAmount, c.commissionAmount, `${c.commissionRate}%`, c.payoutStatus, c.earnedDate]);
    const csv = [headers, ...rows].map((r) => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'commissions.csv'; a.click();
    URL.revokeObjectURL(url);
    toast.success('Exported!');
  };

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 lg:p-8">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">My Commissions</h1>
          <p className="text-sm text-gray-500">{mockCommissions.length} commission entries</p>
        </div>
        <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2.5 bg-emerald-600 text-white text-sm font-semibold rounded-xl shadow-sm hover:bg-emerald-700 transition-colors">
          <Download className="w-4 h-4" /> Export CSV
        </button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
        {[
          { icon: TrendingUp, label: 'Total Earned', value: `₹${totalEarned.toLocaleString('en-IN')}`, color: 'text-[#0B4F6C]', bg: 'bg-[#0B4F6C]/10', gradient: 'from-[#0B4F6C] to-[#00B4D8]', featured: true },
          { icon: CheckCircle, label: 'Total Paid Out', value: `₹${totalPaid.toLocaleString('en-IN')}`, color: 'text-emerald-700', bg: 'bg-emerald-100' },
          { icon: Clock, label: 'Pending Payout', value: `₹${totalPending.toLocaleString('en-IN')}`, color: 'text-amber-700', bg: 'bg-amber-100' },
        ].map(({ icon: Icon, label, value, color, bg, gradient, featured }) => (
          <motion.div key={label} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={`rounded-xl p-5 shadow-sm border ${featured ? `bg-gradient-to-br ${gradient} border-transparent` : `bg-white border-gray-100`}`}>
            <div className={`w-10 h-10 ${featured ? 'bg-white/20' : bg} rounded-xl flex items-center justify-center mb-3`}>
              <Icon className={`w-5 h-5 ${featured ? 'text-white' : color}`} />
            </div>
            <p className={`text-2xl font-black ${featured ? 'text-white' : color}`}>{value}</p>
            <p className={`text-sm mt-0.5 ${featured ? 'text-white/70' : 'text-gray-500'}`}>{label}</p>
          </motion.div>
        ))}
      </div>

      {/* Filter Tabs */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-5">
        <div className="flex gap-1.5 flex-wrap">
          {[
            { value: 'all', label: 'All', count: mockCommissions.length },
            { value: 'paid', label: 'Paid', count: mockCommissions.filter((c) => c.payoutStatus === 'paid').length },
            { value: 'pending', label: 'Pending', count: mockCommissions.filter((c) => c.payoutStatus === 'pending').length },
            { value: 'failed', label: 'Failed', count: mockCommissions.filter((c) => c.payoutStatus === 'failed').length },
          ].map(({ value, label, count }) => (
            <button key={value} onClick={() => setFilter(value)} className={`px-4 py-2 text-sm font-medium rounded-lg transition-all flex items-center gap-1.5 ${filter === value ? 'bg-[#0B4F6C] text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}>
              {label}
              <span className={`px-1.5 py-0.5 text-xs rounded-full ${filter === value ? 'bg-white/20 text-white' : 'bg-gray-200 text-gray-600'}`}>{count}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-100 bg-gray-50/50">
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Commission ID</th>
                <th className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Customer / Package</th>
                <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Booking</th>
                <th className="text-right text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Commission</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3 hidden md:table-cell">Earned</th>
                <th className="text-center text-xs font-semibold text-gray-500 uppercase tracking-wider px-4 py-3">Payout</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((c) => <AgentCommissionRow key={c.id} commission={c} />)}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AgentCommissionsPage;
